# GENERATED by build_stabtests.py from _stabtest_src.py -- edit the source, not this file.
"""BENCHMARK-ONLY regression opponents for "bet when checked to" (stab) strategies (TASK-CLAUDE-010). Not a submission.

One small original source rendered into four folders by build_stabtests.py. They differ ONLY in how they respond
when the hero bets after they have checked on that street (and in how often they check strong hands):

  checkfold90  checks every weak hand and folds ~90% of them to a bet (bets its strong hands itself).
  checkcall50  same, but continues (calls) ~50% of the time after checking.
  checktrap    often CHECKS strong hands, then check-raises them; also check-raises ~15% of weak hands as a bluff
               and calls ~20% more.
  shifter      plays exactly like checkfold90 until the hero has stabbed SHIFT_AFTER times in this match, then plays
               like checktrap for the rest of the match (pattern change after repeated probes).

Purpose: a stab policy should profit from checkfold90, not lose to checkcall50, stop paying off checktrap, and notice
shifter's change. They are deliberately simple and exploitable elsewhere; results say nothing about tournament strength.
Public game_state only (own cards, board, public action log). Deterministic: "chance" is a hash of the hand NUMBER,
own cards, board and street, so it is identical for any hero version or runner. shifter's memory lives in this process
(one match). Imports: eval7, zlib. Written from scratch for this repo.
"""

import zlib

import eval7

PROFILE = "checkfold90"   # rewritten by build_stabtests.py
SHIFT_AFTER = 4
RANKS = "23456789TJQKA"
_STABS_SEEN = set()        # (hand_num, street) pairs in which the hero bet after our check; match-local


def _u(state, salt):
    key = "h%04d|%s|%s|%s" % (state["hand_num"], ",".join(state["your_cards"]), ",".join(state["community_cards"]), salt)
    return (zlib.crc32(key.encode()) & 0xFFFFFFFF) / 4294967296.0


def _score(cards):
    """0..1 preflop strength, coarse: high cards, pairs, suitedness, connectedness."""
    a, b = sorted((RANKS.index(cards[0][0]), RANKS.index(cards[1][0])), reverse=True)
    s = (a * 2.2 + b) / 38.4
    if a == b:
        s = 0.55 + a / 26.0
    if cards[0][1] == cards[1][1]:
        s += 0.06
    if 0 < a - b <= 2:
        s += 0.03
    return min(1.0, s)


def _strong(cards, board):
    """Two pair or better, or a pair made with a hole card that is at least the second-highest board rank."""
    ht = eval7.handtype(eval7.evaluate([eval7.Card(c) for c in list(cards) + list(board)]))
    if ht not in ("High Card", "Pair"):
        return True
    if ht == "Pair":
        br = sorted((RANKS.index(c[0]) for c in board), reverse=True)
        hole = [RANKS.index(c[0]) for c in cards]
        if hole[0] == hole[1]:
            return hole[0] >= br[1]
        return any(h in br and h >= br[1] for h in hole)
    return False


def _raise_to(state, target):
    if state["amount_owed"] >= state["your_stack"]:
        return {"action": "call"}
    cap = state["your_bet_this_street"] + state["your_stack"]
    target = int(max(target, state["min_raise_to"]))
    if target >= cap or cap - target < state["blinds"]["bb"]:
        return {"action": "all_in"}
    return {"action": "raise", "amount": target}


def _mode(state):
    if PROFILE != "shifter":
        return PROFILE
    return "checktrap" if len(_STABS_SEEN) >= SHIFT_AFTER else "checkfold90"


def _preflop(state):
    me = state["seat_to_act"]
    opp = [p for p in state["players"] if p["seat"] != me][0]
    bb = state["blinds"]["bb"]
    eff = min(state["your_stack"] + state["your_bet_this_street"], opp["stack"] + opp["bet_this_street"]) / float(bb)
    s = _score(state["your_cards"])
    raises = sum(1 for e in state["action_log"] if e["street"] == "preflop" and e["action"] in ("raise", "all_in"))
    if eff <= 10:
        if raises == 0 and not state["can_check"]:
            return {"action": "all_in"} if s >= 0.42 else {"action": "fold"}
        if raises == 0:
            return {"action": "all_in"} if s >= 0.75 else {"action": "check"}
        return {"action": "call"} if s >= 0.55 else {"action": "fold"}
    if raises == 0:
        if state["can_check"]:
            return _raise_to(state, 3 * bb) if s >= 0.78 else {"action": "check"}
        return _raise_to(state, int(2.5 * bb)) if s >= 0.36 else {"action": "fold"}
    if raises == 1:
        if s >= 0.80:
            return _raise_to(state, 3 * state["current_bet"])
        return {"action": "call"} if s >= 0.46 else {"action": "fold"}
    if s >= 0.90:
        return {"action": "all_in"}
    return {"action": "call"} if s >= 0.72 else {"action": "fold"}


def _postflop(state):
    me = state["seat_to_act"]
    street = state["street"]
    strong = _strong(state["your_cards"], state["community_cards"])
    u = _u(state, street)
    mode = _mode(state)
    pot, owed = state["pot"], state["amount_owed"]
    here = [e for e in state["action_log"] if e["street"] == street]
    i_checked = any(e["seat"] == me and e["action"] == "check" for e in here)

    if owed == 0:                                           # we may bet or check
        if strong:
            if mode == "checktrap" and u < 0.65:
                return {"action": "check"}                  # trap
            return _raise_to(state, max(state["blinds"]["bb"], int(pot * 0.6)))
        return {"action": "check"}

    if i_checked:                                           # the hero bet after our check: a "stab"
        _STABS_SEEN.add((state["hand_num"], street))
        mode = _mode(state) if PROFILE != "shifter" or len(_STABS_SEEN) > SHIFT_AFTER else "checkfold90"
        if mode == "checkfold90":
            return {"action": "call"} if u < 0.10 else {"action": "fold"}
        if mode == "checkcall50":
            return {"action": "call"} if u < 0.50 else {"action": "fold"}
        if strong:                                          # checktrap
            return _raise_to(state, state["current_bet"] + max(2 * owed, int(pot * 0.7))) if u < 0.75 else {"action": "call"}
        if u < 0.15:
            return _raise_to(state, state["current_bet"] + max(2 * owed, int(pot * 0.7)))
        return {"action": "call"} if u < 0.35 else {"action": "fold"}

    if strong:                                              # facing a bet without having checked (lead or re-raise)
        big = owed / float(max(1, pot - owed))
        if u < 0.25 and big <= 1.0:
            return _raise_to(state, state["current_bet"] + max(2 * owed, int(pot * 0.7)))
        return {"action": "call"}
    return {"action": "fold"}


def decide(game_state: dict) -> dict:
    if game_state.get("type") == "warmup":
        return {"action": "check"}
    try:
        if game_state["street"] == "preflop":
            return _preflop(game_state)
        return _postflop(game_state)
    except Exception:
        return {"action": "check"} if game_state.get("can_check") else {"action": "fold"}
